create extension if not exists pgcrypto;
create table if not exists card_printings(id uuid primary key default gen_random_uuid(),game text not null check(game in('pokemon','magic')),catalog_source text,external_card_id text,tcgplayer_product_id text,canonical_name text not null,printed_name text,set_name text not null,set_code text,collector_number text not null,rarity text,language text not null default 'unknown',region text,stock_image_url text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists listings(id uuid primary key default gen_random_uuid(),card_printing_id uuid not null references card_printings(id) on delete cascade,condition text not null,finish text not null,approved_price_crc integer not null default 0,acquisition_cost numeric(12,2),published boolean not null default false,public_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(card_printing_id,condition,finish));
create table if not exists stock_lots(id uuid primary key default gen_random_uuid(),listing_id uuid not null references listings(id) on delete cascade,location_code text not null default 'UNASSIGNED',quantity integer not null default 0 check(quantity>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists market_prices(id uuid primary key default gen_random_uuid(),listing_id uuid not null references listings(id) on delete cascade,provider text not null,market_price_usd numeric(12,2),market_subtype text,match_confidence text not null default 'unverified',provider_updated_at timestamptz,fetched_at timestamptz not null default now());
create table if not exists price_proposals(id uuid primary key default gen_random_uuid(),listing_id uuid not null references listings(id) on delete cascade,current_price_crc integer not null,suggested_price_crc integer not null,market_price_usd numeric(12,2),status text not null default 'pending' check(status in('pending','approved','rejected')),reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists purchase_requests(id uuid primary key default gen_random_uuid(),request_number text unique not null,fulfillment_method text not null,delivery_fee_crc integer not null default 0,subtotal_crc integer not null,total_crc integer not null,status text not null default 'inquiry',created_at timestamptz not null default now(),confirmed_at timestamptz,confirmed_by uuid);
create table if not exists purchase_request_items(id uuid primary key default gen_random_uuid(),purchase_request_id uuid not null references purchase_requests(id) on delete cascade,listing_id uuid not null references listings(id),requested_quantity integer not null check(requested_quantity>0),price_snapshot_crc integer not null);
create table if not exists inventory_events(id uuid primary key default gen_random_uuid(),listing_id uuid not null references listings(id),quantity_change integer not null,previous_quantity integer not null,new_quantity integer not null,reason text not null,reference_number text,created_by uuid,created_at timestamptz not null default now());
alter table card_printings enable row level security;alter table listings enable row level security;alter table stock_lots enable row level security;alter table market_prices enable row level security;alter table price_proposals enable row level security;alter table purchase_requests enable row level security;alter table purchase_request_items enable row level security;alter table inventory_events enable row level security;
create or replace function is_admin() returns boolean language sql stable security definer set search_path=public as $$select lower(coalesce(auth.jwt()->>'email',''))=any(array['jav22vega@gmail.com','alevegaodio@gmail.com'])$$;
create policy "public read printings" on card_printings for select using(true);create policy "public read published listings" on listings for select using(published=true or is_admin());create policy "public read stock" on stock_lots for select using(true);create policy "admin all printings" on card_printings for all using(is_admin()) with check(is_admin());create policy "admin all listings" on listings for all using(is_admin()) with check(is_admin());create policy "admin all stock" on stock_lots for all using(is_admin()) with check(is_admin());create policy "admin market" on market_prices for all using(is_admin()) with check(is_admin());create policy "admin proposals" on price_proposals for all using(is_admin()) with check(is_admin());create policy "admin inquiries" on purchase_requests for all using(is_admin()) with check(is_admin());create policy "admin inquiry items" on purchase_request_items for all using(is_admin()) with check(is_admin());create policy "admin events" on inventory_events for all using(is_admin()) with check(is_admin());
create or replace view public_listings with (security_invoker=true) as select l.id,l.approved_price_crc,l.condition,l.finish,coalesce(sum(s.quantity),0)::int quantity,jsonb_build_object('canonical_name',c.canonical_name,'set_name',c.set_name,'collector_number',c.collector_number,'language',c.language,'game',c.game,'stock_image_url',c.stock_image_url) card_printings from listings l join card_printings c on c.id=l.card_printing_id left join stock_lots s on s.listing_id=l.id where l.published=true group by l.id,c.id having coalesce(sum(s.quantity),0)>0;
create or replace view admin_inventory with (security_invoker=true) as select l.id listing_id,c.canonical_name,c.set_name,c.collector_number,c.language,l.condition,l.finish,l.published,l.approved_price_crc,coalesce(sum(s.quantity),0)::int quantity,(select mp.market_price_usd from market_prices mp where mp.listing_id=l.id order by fetched_at desc limit 1) market_price_usd from listings l join card_printings c on c.id=l.card_printing_id left join stock_lots s on s.listing_id=l.id group by l.id,c.id;
